Method.Implementation:

	 try{
		do ##super()
		$$$TRACE("Connect to " _ ..ApplicationAddress)
		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.mspr.OaxSsnMsprCheck).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))		
     	set status = ..CheckObject()
	}catch err{
		$$$LOGERROR("Exception while initiating DSQL Tuxedo service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName," Exception while initiating DSQL Tuxedo service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	}

	quit status

 #dim status as %Status	 
 set status = $$$OK
 $$$TRACE("Inside OnMessage method.....")

 	 $$$TRACE("objCdrTuxService Object valid: "_$IsObject(..objCdrTuxService))

 try{

	 if (..CheckObject() '= $$$OK) {
	 	$$$TRACE("**** Object does not exists ****")
	 	// Try to re intialize
	 	set result = ..OnInit()
		if (result '= $$$OK)
		{
			set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Mspr-Oax-Ssn", " getSSN from Mspr failed. Person ID " _pRequest.personId_" id Type: "_pRequest.idType_" ; Reason: " _ result)						
			return status
		}
 	}

	$$$TRACE("Object name: " _ ..objCdrTuxService.%ClassName(1))


	 		$$$TRACE("Calling Cdr Dsql getSSN for the personId# ...,"_pRequest.personId_" id Type: "_pRequest.idType) 				 				 					 				 		
	 		set pResponse=##class(Ens.StringResponse).%New()	
	 		Set pResponse.StringValue = ..objCdrTuxService.getSSN(pRequest.personId, pRequest.idType)
	 		Set respData = pResponse.StringValue		 		
	 		$$$TRACE(" getSSN() returns: "_respData)		 				 			 	
 } catch err {		 	
       Set status = ..ExceptionHandler(err, "OnMessage")
 }

 $$$TRACE("OnMessage status: " _ status)	

 return status
